#!/usr/bin/env python3
import pathlib
import sys


def show_text(path: pathlib.Path, limit: int = 40) -> None:
    print(f"FILE\t{path.name}")
    with path.open("r", encoding="utf-8", errors="replace") as handle:
        for number, line in enumerate(handle, 1):
            print(f"{number}\t{line.rstrip()}" )
            if number >= limit:
                print(f"...\tTRUNCATED_AFTER_{limit}_LINES")
                break


def main() -> None:
    if len(sys.argv) != 3:
        raise SystemExit("usage: inspect_match_archive.py DIRECTORY OUTPUT")
    root = pathlib.Path(sys.argv[1])
    output = pathlib.Path(sys.argv[2])
    files = sorted(p for p in root.rglob("*") if p.is_file())
    with output.open("w", encoding="utf-8") as out:
        old_stdout = sys.stdout
        sys.stdout = out
        try:
            print(f"ROOT\t{root}")
            for path in files:
                print(f"PATH\t{path.relative_to(root)}\tBYTES\t{path.stat().st_size}")
            print()
            for path in files:
                if path.suffix in {".csv", ".psam", ".pvar"}:
                    show_text(path)
                    print()
        finally:
            sys.stdout = old_stdout


if __name__ == "__main__":
    main()

